var DATA_DIR = join(dirname(fileURLToPath(new URL(".", import.meta.url))), "data");
var DB_PATH = join(DATA_DIR, "stats.db");
var _db = null;
function openDb() {
  if (_db) return _db;
  try {
    mkdirSync(DATA_DIR, { recursive: true });
    const db = new DatabaseSync(DB_PATH);
    db.exec(`
      CREATE TABLE IF NOT EXISTS usage_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ts INTEGER NOT NULL,
        kind TEXT NOT NULL,
        sub TEXT,
        ok INTEGER NOT NULL DEFAULT 0,
        fail INTEGER NOT NULL DEFAULT 0,
        cost REAL NOT NULL DEFAULT 0,
        tokens_in INTEGER NOT NULL DEFAULT 0,
        tokens_out INTEGER NOT NULL DEFAULT 0,
        cached_tokens INTEGER NOT NULL DEFAULT 0
      );
      CREATE INDEX IF NOT EXISTS idx_usage_ts ON usage_log(ts);
      CREATE INDEX IF NOT EXISTS idx_usage_kind ON usage_log(kind);
      CREATE TABLE IF NOT EXISTS group_stats (
        group_id INTEGER PRIMARY KEY,
        msg INTEGER NOT NULL DEFAULT 0,
        reply INTEGER NOT NULL DEFAULT 0,
        last_at INTEGER
      );
      CREATE TABLE IF NOT EXISTS mined_profile (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        json TEXT NOT NULL,
        updated_at INTEGER NOT NULL
      );
    `);
    const cols = db.prepare(`PRAGMA table_info(usage_log)`).all().map((c) => c.name);
    if (!cols.includes("duration_ms")) db.exec(`ALTER TABLE usage_log ADD COLUMN duration_ms INTEGER NOT NULL DEFAULT 0`);
    if (!cols.includes("ttft_ms")) db.exec(`ALTER TABLE usage_log ADD COLUMN ttft_ms INTEGER NOT NULL DEFAULT 0`);
    if (!cols.includes("cached_tokens")) db.exec(`ALTER TABLE usage_log ADD COLUMN cached_tokens INTEGER NOT NULL DEFAULT 0`);
    _db = db;
    return db;
  } catch (e) {
    console.warn("[Stats] \u6253\u5F00 stats.db \u5931\u8D25\uFF08\u7EDF\u8BA1\u7981\u7528\uFF09:", e.message);
    return null;
  }
}
