function recordUsage(rec) {
  const db = openDb();
  if (!db) return;
  try {
    db.prepare(
      `INSERT INTO usage_log(ts, kind, sub, ok, fail, cost, tokens_in, tokens_out, duration_ms, ttft_ms, cached_tokens)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(
      rec.ts,
      rec.kind,
      rec.sub ?? "",
      rec.ok,
      rec.fail,
      rec.cost,
      rec.tokensIn,
      rec.tokensOut,
      Math.round(rec.durationMs ?? 0),
      Math.round(rec.ttftMs ?? 0),
      Math.round(rec.cachedTokens ?? 0)
    );
  } catch (e) {
    console.warn("[Stats] \u5199\u5165\u5931\u8D25:", e.message);
  }
}
function recordGroupMsg(groupId) {
  const db = openDb();
  if (!db) return;
  try {
    db.prepare(
      `INSERT INTO group_stats(group_id, msg, reply, last_at)
       VALUES (?, 1, 0, ?)
       ON CONFLICT(group_id) DO UPDATE SET
         msg = msg + 1,
         last_at = excluded.last_at`
    ).run(groupId, Date.now());
  } catch {
  }
}
function recordGroupReply(groupId) {
  const db = openDb();
  if (!db) return;
  try {
    db.prepare(
      `INSERT INTO group_stats(group_id, msg, reply, last_at)
       VALUES (?, 0, 1, ?)
       ON CONFLICT(group_id) DO UPDATE SET
         reply = reply + 1,
         last_at = excluded.last_at`
    ).run(groupId, Date.now());
  } catch {
  }
}
