function buildSystemPrompt(scene) {
  const template = scene === "private" && config.persona.privateSystemPromptTemplate ? config.persona.privateSystemPromptTemplate : config.persona.systemPromptTemplate;
  let prompt = template.replace(/\{name\}/g, config.persona.name).replace(/\{friend\}/g, config.persona.friendName).replace(/\{rag\}/g, "");
  if (config.persona.demoDialogs) {
    const lines = config.persona.demoDialogs.split("\n").map((l) => l.trim()).filter(Boolean);
    if (lines.length) {
      prompt += "\n\n\u3010\u771F\u5B9E\u5BF9\u8BDD\u793A\u4F8B\u3011\uFF08\u8FD9\u662F\u4F60\u548C\u670B\u53CB\u5E73\u65F6\u771F\u5B9E\u7684\u804A\u5929\uFF0C\u7167\u8FD9\u4E2A\u5473\u9053\u6765\uFF09\n" + lines.join("\n").replace(/^本人:/gm, `${config.persona.name}:`);
    }
  }
  prompt += `
## \u5DE5\u5177
\u5DE5\u5177\u662F\u552F\u4E00\u884C\u52A8\u65B9\u5F0F\uFF0C\u540D\u5B57\u7CBE\u786E\u8C03\u7528\uFF1A
- reply(text)\uFF1A\u5F00\u53E3\u8BF4\u4E00\u53E5\u3002\u53EF\u4E00\u6B21\u8FD4\u56DE\u591A\u6761\uFF0C\u6BCF\u6761\u5C31\u662F\u4E00\u6761\u6D88\u606F\uFF08\u6309\u6761\u53D1\u9001\uFF0C\u4E0D\u62C6\u5206\uFF09\u3002
- search_past_memory(query)\uFF1A\u5524\u9192\u8BB0\u5FC6\u2014\u2014\u67E5\u4F60\u771F\u5B9E\u8BF4\u8FC7\u7684\u539F\u8BDD\u3002
- remember(note)\uFF1A\u8BB0\u4F4F\u5173\u4E8E\u670B\u53CB\u7684\u7A33\u5B9A\u4E8B\u5B9E/\u559C\u597D/\u7EA6\u5B9A\u3002

## \u56DE\u590D
- \u8981\u8BF4\u8BDD\u5C31\u8C03 reply\uFF0C\u5185\u5BB9\u5C31\u662F\u4F60\u5BF9\u670B\u53CB\u8BF4\u7684\u8BDD\u672C\u8EAB\u3002
- \u60F3\u5206\u51E0\u6761\u8BF4\u5C31\u8C03\u7528\u51E0\u6B21 reply\uFF0C\u6BCF\u6761\u4E00\u53E5\uFF1B\u4E0D\u8981\u628A\u51E0\u6761\u62FC\u6210\u4E00\u6761\u91CC\u7528\u6362\u884C\u3002
- \u56DE\u5FC6/\u786E\u8BA4\u5F80\u4E8B\u5148 search_past_memory\uFF1B\u60F3\u4E0D\u8D77\u5C31\u76F4\u8BF4"\u8BB0\u4E0D\u6E05\u4E86/\u5FD8\u4E86"\uFF0C\u522B\u8BF4\u662F"\u7FFB\u4E86\u7FFB\u8BB0\u5FC6/\u68C0\u7D22/\u67E5\u8BB0\u5FC6"\u2014\u2014\u4F60\u8BF4\u8BDD\u5C31\u662F\u4EBA\u8BDD\u3002`;
  return prompt;
}

