// transport/http/http.ts
function json(res, code, obj) {
  res.writeHead(code, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(obj));
}
function readBody(req, lim = 2 * 1024 * 1024) {
  return new Promise((resolve2, reject) => {
    const chunks = [];
    let size = 0;
    req.on("data", (c) => {
      size += c.length;
      if (size > lim) {
        reject(new Error("body too large"));
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      try {
        const raw = Buffer.concat(chunks).toString("utf8");
        resolve2(raw ? JSON.parse(raw) : {});
      } catch {
        reject(new Error("bad json"));
      }
    });
  });
}

// transport/http/router.ts
var Router = class {
  entries = [];
  get(path2, handler) {
    return this.add("GET", path2, handler);
  }
  post(path2, handler) {
    return this.add("POST", path2, handler);
  }
  add(method, path2, handler) {
    this.entries.push({ method, match: (p) => p === path2, handler });
    return this;
  }
  /** 命中并处理返回 true；未命中返回 false（交给后续路由/兜底） */
  async dispatch(ctx) {
    for (const e of this.entries) {
      if (e.method !== ctx.req.method) continue;
      if (!e.match(ctx.path)) continue;
      await e.handler(ctx);
      return true;
    }
    return false;
  }
};

// transport/http/routes/models.ts
function registerModelsRoutes(r) {
  r.get("/api/models", async ({ res }) => {
    const active = getActiveProvider();
    const providers = listProviders().map((p) => ({
      id: p.id,
      name: p.name,
      model: p.model,
      baseUrl: p.baseUrl,
      pricePerMIn: p.pricePerMIn,
      pricePerMOut: p.pricePerMOut,
      fallback: p.fallback ?? [],
      active: active?.id === p.id
    }));
    json(res, 200, {
      active: active?.id ?? null,
      providers,
      remote: await listModels()
    });
  });
  r.get("/api/models/health", async ({ res }) => {
    json(res, 200, { health: await healthCheckAll() });
  });
  r.post("/api/models/switch", async ({ req, res }) => {
    const body = await readBody(req);
    const r2 = setActiveProvider(String(body.id || ""));
    if (!r2.ok) return json(res, 400, { error: r2.error });
    json(res, 200, { ok: true, active: r2.active?.id });
  });
  r.post("/api/models/test", async ({ req, res }) => {
    const body = await readBody(req);
    const id = String(body.id || "");
    const spec = getProvider(id);
    if (!spec) return json(res, 400, { error: "unknown provider" });
    json(res, 200, { id, ...await testProvider(spec) });
  });
}

